import {
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import {
  uniform,
  uv,
  vec2,
  vec3,
  mix,
  smoothstep,
  time,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, TextureLoader } = THREE;

  // --- Extract config ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const imageUrl = config.imageUrl || null;
  const position = config.scenePosition || { x: -3.2, y: 1, z: 0.06 };
  const colors = config.intent?.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // --- Build group ---
  const group = new Group();
  group.position.set(position.x, position.y, position.z);

  // --- Load texture ---
  let mapTexture = null;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      mat.map = tex;
      mat.needsUpdate = true;
    });
  }

  // --- Create plane geometry ---
  const geometry = new PlaneGeometry(1.8, 1.2);

  // --- Create material with brushed metal appearance ---
  const mat = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.95,
  });

  // Add subtle grain via node material
  const grainAmount = uniform(0.03);
  const grainUv = uv().mul(vec2(512, 320));
  const grain = smoothstep(0.3, 0.7, grainUv.x.add(grainUv.y).mul(0.5).fract());
  const baseColor = vec3(colors.surface);
  const grainColor = vec3(colors.ink);
  mat.colorNode = mix(baseColor, grainColor, grain.mul(grainAmount));

  // --- Create mesh ---
  const mesh = new Mesh(geometry, mat);
  group.add(mesh);

  // --- Add headline text ---
  const headlineItem = items.find(item => item.role === 'headline' || item.text?.includes('Journal'));
  if (headlineItem) {
    const textContent = headlineItem.text || 'Journal 1';
    const fontSize = headlineItem.typography?.fontSize || 39;
    const textMesh = ctx.fontAtlas.createText(textContent, {
      fontSize: fontSize * 0.02,
      color: colors.paper,
      align: 'center',
      maxWidthPx: 280,
    });
    if (textMesh) {
      textMesh.position.set(0, 0.25, 0.01);
      group.add(textMesh);
    }
  }

  // --- Add accent line ---
  const lineGeo = new PlaneGeometry(0.6, 0.008);
  const lineMat = new MeshBasicNodeMaterial({ color: colors.accent });
  const line = new Mesh(lineGeo, lineMat);
  line.position.set(0, -0.1, 0.01);
  group.add(line);

  // --- Add subtle paper label ---
  const labelText = ctx.fontAtlas.createText('READ MORE', {
    fontSize: 0.055,
    color: colors.accent,
    align: 'center',
    letterSpacingPx: 1.5,
  });
  if (labelText) {
    labelText.position.set(0, -0.35, 0.01);
    group.add(labelText);
  }

  // --- Add journal date indicator ---
  const dateText = ctx.fontAtlas.createText('VOL. I', {
    fontSize: 0.045,
    color: colors.ink,
    align: 'center',
    letterSpacingPx: 2,
  });
  if (dateText) {
    dateText.position.set(0, 0.42, 0.01);
    group.add(dateText);
  }

  // --- Contact shadow plane ---
  const shadowGeo = new THREE.CircleGeometry(1.1, 32);
  const shadowMat = new MeshBasicNodeMaterial({
    color: colors.ink,
    transparent: true,
    opacity: 0.25,
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -0.65, -0.02);
  shadow.rotation.x = -Math.PI / 2;
  group.add(shadow);

  // --- Event handlers ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    geometry.dispose();
    mat.dispose();
    lineMat.dispose();
    shadowMat.dispose();
    if (mapTexture) mapTexture.dispose();
    // Kill any GSAP timelines
    if (group.userData._timeline) {
      group.userData._timeline.kill();
    }
  };

  return group;
}
